def sync_sfs(apps, schema_editor):
    GuidelineCategory = apps.get_model('debt_app', 'GuidelineCategory')
    ExpenditureGuideline = apps.get_model('debt_app', 'ExpenditureGuideline')

    # 1. Canonical categories: get-or-create by name, force sort_order to match.
    groups = {}
    for name, sort_order in CATEGORY_ORDER:
        group, _ = GuidelineCategory.objects.get_or_create(name=name)
        if group.sort_order != sort_order:
            group.sort_order = sort_order
            group.save(update_fields=['sort_order'])
        groups[name] = group

    # 2. Upsert every guideline row from the live case-assessment dataset.
    for row in GUIDELINES:
        group = groups[row['category_group_name']]
        defaults = {
            'label': row['label'],
            'category_group': group,
            'sort_order': int(row['sort_order']),
            'min': bool(row['min']),
            'max': bool(row['max']),
            'formula': row.get('formula', ''),
            'below_action': row.get('below_action', ''),
            'above_action': row.get('above_action', ''),
            'mismatch_action': row.get('mismatch_action', ''),
            'notes': row.get('notes', ''),
            'aryza_aliases': row.get('aryza_aliases', ''),
        }
        for field in NUMERIC_FIELDS:
            raw = row.get(field, '0.00')
            try:
                defaults[field] = Decimal(str(raw))
            except Exception:
                defaults[field] = Decimal('0.00')

        ExpenditureGuideline.objects.update_or_create(
            category=row['category'],
            defaults=defaults,
        )

    # 3. Remove dead/superseded rows.
    ExpenditureGuideline.objects.filter(category__in=REMOVE_SLUGS).delete()

    # 4. Remove orphan duplicate categories once they hold no guidelines.
    for name in REMOVE_CATEGORY_NAMES:
        GuidelineCategory.objects.filter(name=name, guidelines__isnull=True).delete()


